    private static Variant Get(Settings data,string key,Variant fallback=default)=>data.TryGetValue(key,out var value)?value:fallback;
    private static double Value(Settings data,string key,double fallback=0)=>data.TryGetValue(key,out var value)?value.AsDouble():fallback;
    private static string Text(Settings data,string key,string fallback="")=>data.TryGetValue(key,out var value)?value.AsString():fallback;
    private static bool Enabled(Settings data)=>!data.TryGetValue("enabled",out var enabled)||enabled.AsBool();
    private static Settings Parameters(Settings effect)=>effect.TryGetValue("parameters",out var value)?value.AsGodotDictionary():new Settings();
    public Settings parameter(string id,string label,double value,double minimum,double maximum,double step)=>new() {["id"]=id,["label"]=label,["default"]=value,["min"]=minimum,["max"]=maximum,["step"]=step};
    public Godot.Collections.Array<Settings> catalog(){var result=new Godot.Collections.Array<Settings>();foreach(var raw in Json.ParseString(CatalogRows).AsGodotArray()){var row=raw.AsGodotArray();result.Add(entry(row[0].AsString(),row[1].AsString(),row[2].AsString(),row[3].AsBool(),row[4].AsGodotArray()));}return result;}
    public Settings entry(string id,string label,string category,bool realtime,GArray parameters)
    {
        string description;if(id=="dereverb")description="Offline multiband decay suppression, not perfect dry-speech reconstruction. Protects onsets/sustained energy and attenuates falling tails using estimated RT60. May reduce intended musical tails; compare/bypass before baking. Static controls, 64 MiB stage and 60-second processing limits.";else if(id=="breath")description="Offline level-based downward expansion of quiet passages. It can reduce low-level room noise or breaths, but cannot classify breaths, remove reverberation or separate speech from noise. Preview before applying; quiet speech can also be reduced.";else if(id=="doppler")description="Offline moving-source propagation delay at 343 m/s, with an eased subsonic pass. Static controls; clip time starts at the clip, track/master time at the timeline. Wet audio keeps its acoustic arrival delay; dry stays aligned. Resampling rolls off high frequencies to limit aliasing. No sonic boom, reflections, air loss or HRTF.";else description=realtime?(id=="compressor"?"Native approximation (compressor attack capped at 2 ms); render preview for exact offline result":"Native approximation; render preview to hear the exact offline result"):"Offline processor; render preview to hear exact result";if(id is "hq_pitch" or "formant" or "time_warp")label+=" (Rubber Band)";return new Settings {["id"]=id,["label"]=label,["category"]=category,["realtime"]=id is "dereverb" or "breath" or "doppler"?false:realtime,["parameters"]=parameters,["description"]=description};
    }
    public Settings definition(string id){foreach(var entry in catalog())if(Text(entry,"id")==id)return entry;return new Settings();}
    public Settings create(string id){var entry=definition(id);if(entry.Count==0)return new Settings();var parameters=new Settings();foreach(var raw in entry["parameters"].AsGodotArray()){var field=raw.AsGodotDictionary();parameters[field["id"]]=field["default"];}return new Settings {["id"]=ActorData.new_id(),["type"]=id,["enabled"]=true,["parameters"]=parameters,["automation"]=new Settings()};}
    public static string FormatNumber(Variant value){double number=value.AsDouble();return (double.IsFinite(number)?number:0).ToString("F8",CultureInfo.InvariantCulture);}
    public string number(Variant value)=>FormatNumber(value);
    public string tempo_filter(double speed){var filters=new List<string>();speed=Math.Clamp(speed,.015625,64);while(speed<.5){filters.Add("atempo=0.5");speed*=2;}while(speed>2){filters.Add("atempo=2");speed*=.5;}filters.Add("atempo="+number(speed));return string.Join(',',filters);}
    public string pan_filter(double pan){pan=Math.Clamp(pan,-1,1);return "pan=stereo|c0="+number(Math.Min(1,1-pan))+"*c0|c1="+number(Math.Min(1,1+pan))+"*c1";}
}
